head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.arrPar = [];
scwin.empNo = ""; // 로그인 사번
scwin.empNm = ""; // 로그인 성명
scwin.email = ""; // 로그인 이메일

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15700.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 세션 사용자 정보 보관, 기본 검색값·버튼 비활성·숨김 항목 설정, 공통코드 콤보 조회, Enter 조회 바인딩
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    // 세션 정보
    scwin.empNo = $c.session.getUserInfo("empNo");   // 사원번호
    scwin.empNm = $c.session.getUserInfo("empNm");   // 사용자이름
    scwin.email = $c.session.getUserInfo("email");   // 사용자 Email

    txb_pSTD_CD.setValue("KRA");

    // 버튼 비활성화
    btn_modify.setDisabled(true);
    btn_delete.setDisabled(true);
    btn_file.setDisabled(true);
    btn_prcnm.setDisabled(true);
    btn_clearPwd.setDisabled(true);

    txb_OBJ_STK_ISU_CD.hide();
    txb_OBJ_BND_ISU_CD.hide();
    txb_DEL_RSN.hide();
    txb_param1.hide();
    txb_param2.hide();
    txa_REF_CONTN.hide();
    // 비밀번호초기화 버튼 숨김
    btn_clearPwd.hide();

    txb_pSTD_CD.focus();

    // 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 값을 DataCollection에 저장하고 objFunc 함수를 실행
    $c.win.setEnterKeyEvent(tblSearch, scwin.btn_search_onclick);

    // 조회 기간 선후 자동 보정 바인딩(gcc compareFromToDate — onviewchange 시 시작일·종료일 검사)
    $c.date.compareFromToDate(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE, ["발행일 시작일", "발행일 종료일"]);
    $c.date.compareFromToDate(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE, ["코드부여일 시작일", "코드부여일 종료일"]);
    // 공통코드 selectbox 셋팅(통신 — UI 초기 설정 뒤에 수행)
    await scwin.setComboCode();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_search_onclick
 * @description 조회
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15700.btn_search_onclick" });
    }
};

/**
 * @method
 * @name txb_pSTD_CD_onkeyup
 * @description 표준코드
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_pSTD_CD_onkeyup = function (e) {
    try {
        scwin.delSpecialChar(txb_pSTD_CD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS15700.txb_pSTD_CD_onkeyup" });
    }
};

