/**
 * @method
 * @name cmb_FORN_COM_YN_onchange
 * @description 국내/외국기업
 * @param {Object} info 이벤트 정보 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_FORN_COM_YN_onchange = async function (info) {
    try {
        if (cmb_FORN_COM_YN.getValue() === "Y") {
            txb_pSTD_CD.setValue("");
        } else {
            txb_pSTD_CD.setValue("KRA");
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15700.cmb_FORN_COM_YN_onchange" });
    }
};

/**
 * @method
 * @name grd_bwMgtList_oncellclick
 * @description grd_bwMgtList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_bwMgtList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const stdCd = dlt_bwMgtList.getDataRow(rowIndex).stdCd;
        await scwin.searchDetail(stdCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15700.grd_bwMgtList_oncellclick" });
    }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 수정
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function (e) {
    try {
        if (await scwin.modify("N") === false) return;
        // fn_make_fisn();
        txb_DEL_RSN.setValue("");
        await scwin.openInsPopup(txb_DEL_RSN, "", "ULDINS93900", "수정사유", "470", "340");
        // 수정사유가 입력되면 저장 처리(AS-IS 는 팝업이 opener 의 ins_modify 를 직접 호출)
        if (!$c.util.isEmpty(txb_DEL_RSN.getValue())) await scwin.modify("Y");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15700.btn_modify_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 삭제
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function (e) {
    try {
        // if (fn_checkSendTime()==false) { alert("정보문의 전송 마감시간(19:00)이 초과되어 삭제하실수 없습니다."); return; }
        txb_param1.setValue("");
        txb_param2.setValue("");
        scwin.getParam();
        // 삭제 신청건수 확인후
        const delcnt = dma_bwMgtDetail.get("delcnt");
        // console.log("delcnt"+delcnt);
        if (delcnt > 0) {
            // 삭제 메시지 확인 ... 확인되면 -> 삭제승인 화면이동 ,null,null, 아니면 바로 삭제
            await scwin.alertRequiredDelByWeb();
        } else {
            // 관리 삭제로직
            // 삭제팝업호출
            // 삭제사유 전달받을 input박스 정의한다.
            if (!(await $c.win.confirm("삭제하시겠습니까?"))) return; // AS-IS $c.cm.alertDelConfirm(미반입) 대체
            txb_DEL_RSN.setValue("");
            await scwin.openInsPopup(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "350");
            // 삭제사유가 입력되면 삭제 처리(AS-IS 는 팝업이 opener 의 ins_remove 를 직접 호출)
            if (!$c.util.isEmpty(txb_DEL_RSN.getValue())) await scwin.remove();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15700.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_file_onclick
 * @description 첨부파일확인
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_file_onclick = async function(e) {
    try {
        /*
        txb_param1 에는 신청ID
        txb_param2 에는 구분값을 넣는데..
        + "1 : 발행기관신청, 팩스-발행기관신청 \n"
        + "2 : 표준코드신청, 팩스-표준코드신청 \n"
        + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
         */
        txb_param1.setValue(txb_STD_CD_APPL_ID.getValue()); // 표준코드  신청 ID
        txb_param2.setValue("2");
        scwin.getParam();

        await scwin.openInsPopup("", "", "ULDINS91100", "첨부파일", "655", "550");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS15700.btn_file_onclick" });
    }
};

