    try {
        const svcRunYn = dma_bwMgtDetail.get("svcRunYn");    // 메일 작동여부  TBLD_SVC_STAT - ETC01

        // 데이터셋 ,
        // 화면ID ,
        // 03수정 ,
        // 0 : 발행기관  1: 표준코드 ,
        // 신청ID
        const key = txb_STD_CD_APPL_ID.getValue(); // 표준코드  신청 ID

        // TODO Stage2: 비밀번호 초기화 공통(insClearPwd) 은 Gauce 트랜잭션 잔재 — API 전환 후 재구현: $c.cm.insClearPwd("", scwin.vScrenID, scwin.SCREN_PROCS_TP_CD_03, "1", key, svcRunYn);

    /*
        scwin.trs_pwd_OnSuccess = function() {
            alert("비밀번호 초기화 완료 후 메일 발송 완료 하였습니다.");
        };
     */
