/**
 * @method
 * @name cmb_cb_p_attr_3_onchange
 * @description CFI 3차속성
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_attr_3_onchange = function (info) {
    try {
        scwin.changeCfi();
    } catch (ex) {
