 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setComboCode = async function (){
    /**
     * CURR_TP_CD               발행통화(0:기타.1:원화,2:달러,3:엔화,...9:싱가폴달러)
     * FORN_SECU_KIND_CD        해외증권종류(1:해외CB,2:해외BW주,3:해외DR,9:기타)
     * DOM_FORN_STKCERT_TP_CD   국내/해외주권 발행구분(D:국내,I:해외)
     * COM_ATTR_TP_CD           회사속성(1:주권,2:투자회사,3:유동화회사,4:부동산투자회사,...9:기타)
     * SPOT_ISU_TRD_MKT_TP_CD   시장구분(1:유가증권시장,2:코스닥시장,5:프리보드,6:코넥스시장,9:기타)
     * LIST_STAT_CD             상장여부(D:상장폐지,I:미발행,N:비상장,Y:상장,Z:기타)
     * STD_CD_APCT_TP_CD        신청인 구분(1:발행기관,2:대표주관회사,3:채권부,4:기타,5:온라인소액투자중개업자)
     */

    dma_searchCode.set("codeList", "CURR_TP_CD,BND_STKCERT_TP_CD,DOM_FORN_STKCERT_TP_CD,LIST_STAT_CD,STD_CD_APCT_TP_CD");

    const sbmOptions = {
        id : "sbm_searchCode",
        action : "/api/isin/common/api/commCode/commCodeValue-select",
        method : "get",
        ref : "dma_searchCode",
        target : "dlt_CURR_TP_CD=body.CURR_TP_CD,dlt_BND_STKCERT_TP_CD=body.BND_STKCERT_TP_CD,dlt_DOM_FORN_STKCERT_TP_CD=body.DOM_FORN_STKCERT_TP_CD,dlt_LIST_STAT_CD=body.LIST_STAT_CD,dlt_STD_CD_APCT_TP_CD=body.STD_CD_APCT_TP_CD",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    if (sbmRtn && sbmRtn.skipped) return;
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler scwin.sbm_searchCode_submitdone 미정의)
};

