                txb_ISU_ENG_ABBRV : { required : true, name : "영문종목약명" }
            }
        });
        if (!isValid) return false;
        // byte 길이 검사(AS-IS 규약: 한글 2byte — $c.fil.checkMaxLength 가 초과 시 알림·포커스)
        if (!$c.fil.checkMaxLength(txb_STD_CD, 12, "표준코드")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) return false;
        if (!$c.fil.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) return false;
        if (!$c.fil.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) return false;
/*
        //CFI체크
        if (cmb_cb_p_group.getValue() == "") {
            await $c.win.alert("[CFI_그룹] 을(를) 입력하셔야 합니다.");
            cmb_cb_p_group.focus();
            return false;
        }
        if (cmb_cb_p_attr_1.getValue() == "") {
            await $c.win.alert("[CFI_1차속성] 을(를) 입력하셔야 합니다.");
            cmb_cb_p_attr_1.focus();
            return false;
        }
        if (cmb_cb_p_attr_2.getValue() == "") {
            await $c.win.alert("[CFI_2차속성] 을(를) 입력하셔야 합니다.");
            cmb_cb_p_attr_2.focus();
            return false;
        }
        if (cmb_cb_p_attr_3.getValue() == "") {
            await $c.win.alert("[CFI_3차속성] 을(를) 입력하셔야 합니다.");
            cmb_cb_p_attr_3.focus();
            return false;
        }
        if (cmb_cb_p_attr_4.getValue() == "") {
            await $c.win.alert("[CFI_4차속성] 을(를) 입력하셔야 합니다.");
            cmb_cb_p_attr_4.focus();
            return false;
        }
 */

        if (mflag === "N") return;

        dma_modify.setJSON(dma_bwMgtDetail.getJSON());
        dma_modify.set("transtrEmpNo", scwin.empNo);
        dma_modify.set("empNm", scwin.empNm);
        dma_modify.set("chgRsn", txb_DEL_RSN.getValue());

        const sbmOptions = {
