/**
 * @method
 * @name createStdIsuNm
 * @description 주권 종목명 생성
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.createStdIsuNm = async function() {
    dma_searchIsuNm.undo();
    dma_searchIsuNm.set("isurCd", txb_ISUR_CD.getValue());
    dma_searchIsuNm.set("stkcertKindTpCd", "C");

    const sbmOptions = {
        id : "sbm_preferIsuNm",
        action : "/api/isin/api/stdcdMgtGrp/stkcertMgt/stkcertMgtBasNmPreferShare-select",
        method : "get",
        ref : "dma_searchIsuNm",
        target : "dma_getIsuNm=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) return;

    /*
4. 신주인수권증서 R
- 한글종목명 : 발행기관명+발행회차+R
- 한글종목약명 : 발행기관약명+발행회차+R
- 영문종목명 : 발행기관명(영)+발행회차+R
- 영문종목약명 : 발행기관명(영)+발행회차+R
     * 주권의 기준종목명 테이블에 정보가 있는 경우 그 정보를 가져와 +이후 규칙대로.

5. 신주인수권증권 WR
- 한글종목명 : 발행기관명+발행회차+WR
- 한글종목약명 : 발행기관약명+발행회차+WR
- 영문종목명 : 발행기관명(영)+발행회차+WR
- 영문종목약명 : 발행기관명(영)+발행회차+WR
     * 주권의 기준종목명 테이블에 정보가 있는 경우 그 정보를 가져와 +이후 규칙대로.
     */
    if ($c.util.isEmpty(res.responseJSON.body)) {
        await $c.win.alert("해당 주권종류 코드가 존재하지 않습니다.");
        return;
    }

    let A = dma_getIsuNm.get("comNm");
    let B = dma_getIsuNm.get("comAbbrv");
    let C = dma_getIsuNm.get("comEngNm");
    let D = dma_getIsuNm.get("comEngAbbrv");
    const E = dma_getIsuNm.get(""); // 기존 주권의 보통주 존재여부 — TODO Stage2: 응답 키 미정(AS-IS NameValue(1, "E")) — API 응답 확인 후 키 지정

    A = A.replace("보통주", "").trim();
    B = B.replace("보통주", "").trim();
    C = C.replace("보통주", "").trim();
    D = D.replace("보통주", "").trim();

    const WRNT_ISU_RND = edt_WRNT_ISU_RND.getValue();

    const str_bnd_stkcert_tp_cd = dma_bwMgtDetail.get("bndStkcertTpCd");
    let bnd_stkcert_tp_cd = "";
    if (str_bnd_stkcert_tp_cd === "2") {
        bnd_stkcert_tp_cd = WRNT_ISU_RND + "R";
    } else if (str_bnd_stkcert_tp_cd === "1" || str_bnd_stkcert_tp_cd === "3") {
        bnd_stkcert_tp_cd = WRNT_ISU_RND + "WR";
    }
    if (E === "Y") {
        //     주권에존재
        txb_ISU_NM.setValue(A);
        txb_ISU_ABBRV.setValue(B);
        txb_ISU_ENG_NM.setValue(C);
        txb_ISU_ENG_ABBRV.setValue(D);
    } else {
        //     주권에미존재
        txb_ISU_NM.setValue(A + " " + bnd_stkcert_tp_cd);
        txb_ISU_ABBRV.setValue(B + " " + bnd_stkcert_tp_cd);
        txb_ISU_ENG_NM.setValue(C + " " + bnd_stkcert_tp_cd);
        txb_ISU_ENG_ABBRV.setValue(D + " " + bnd_stkcert_tp_cd);
    }
};

